css:
.morse-wc {
  min-height: 16px;
  padding: 4px 14px 0;
  text-align: right;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--text-tertiary, #8f8f8f);
}

js:
morse.watch("#prompt-textarea", box => {
  const form = box.closest("form");
  if (!form) return;
  const badge = morse.el("div", { class: "morse-wc", "aria-live": "polite" });
  const count = () => {
    const text = (box.value ?? box.innerText ?? "").trim();
    const words = text ? text.split(/\s+/).length : 0;
    badge.textContent = words
      ? words + (words === 1 ? " word" : " words") + " · " + text.length + " chars"
      : "";
  };
  morse.on(box, "input", count);
  form.after(badge);
  count();
});
